<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Browse Police Jurisdictions</title>
<style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f4f7f6;color:#2c3e50}.hero{background:linear-gradient(135deg,#1a252f,#2c3e50);color:#fff;padding:56px 20px}.hero-inner,.container{max-width:1120px;margin:0 auto}.hero h1{margin:0;font-size:34px}.hero p{color:#bdc3c7}.container{padding:32px 20px 56px}.toolbar{background:#fff;border-radius:12px;box-shadow:0 8px 24px rgba(26,37,47,.08);padding:18px;margin-top:-54px;position:relative}.toolbar form{display:grid;grid-template-columns:1fr auto;gap:12px}.toolbar input{border:1px solid #d8e0e6;border-radius:8px;padding:12px}.toolbar button{border:1px solid #bae6fd;border-radius:8px;background:#f0f9ff;padding:0 22px;color:#0369a1;font-weight:bold}.split{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;margin-top:28px}.browser{background:#fff;border-radius:14px;box-shadow:0 8px 24px rgba(26,37,47,.08);overflow:hidden}.browser-head{padding:20px 22px;border-bottom:1px solid #edf1f4}.viewport{padding:22px}.hq-card{display:none;min-height:280px;border:1px solid #edf1f4;border-radius:14px;padding:24px}.hq-card.active{display:flex;flex-direction:column}.hq-card h3{font-size:23px}.view{margin-top:auto;color:#0369a1;font-weight:bold;text-decoration:none}.controls{display:flex;justify-content:space-between;align-items:center;margin-top:18px}.controls button{width:38px;height:38px;border:1px solid #cbd5e1;border-radius:50%;background:#fff}@media(max-width:800px){.split{grid-template-columns:1fr}}</style></head>
