@foreach([['Metropolitan Police',$metroHqs],['District Police',$districtHqs]] as [$title,$rows])<article class="browser" data-browser><header class="browser-head"><h2>{{$title}}</h2><p>{{$rows->count()}} headquarters</p></header><div class="viewport">@forelse($rows as $row)<section class="hq-card" data-card><p class="text-sky-600">{{$row->head_rank}}</p><h3>{{$row->name}}</h3><p>{{$row->district}} · {{$row->division}}</p><p>{{$row->thanas_count}} thana(s)</p><a class="view" href="{{route('stations.show',$row)}}">View Thanas</a></section>@empty<p>No headquarters found.</p>@endforelse<div class="controls"><button type="button" data-prev>&lsaquo;</button><span data-position>0/0</span><button type="button" data-next>&rsaquo;</button></div></div></article>@endforeach
</section></main><script>document.querySelectorAll('[data-browser]').forEach(b=>{const c=[...b.querySelectorAll('[data-card]')],p=b.querySelector('[data-position]');let i=0;const r=()=>{c.forEach((x,n)=>x.classList.toggle('active',n===i));p.textContent=c.length?`${i+1}/${c.length}`:'0/0'};b.querySelector('[data-prev]').onclick=()=>{if(c.length){i=(i-1+c.length)%c.length;r()}};b.querySelector('[data-next]').onclick=()=>{if(c.length){i=(i+1)%c.length;r()}};r()})</script></body></html>
